import{z as l,x as s,o as B,c as p,q as n,j as o,D as e,d as E,s as A,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"风险调整绩效的族谱","description":"","frontmatter":{"title":"风险调整绩效的族谱","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-riskadjusted-family.md","filePath":"quant/ap-riskadjusted-family.md","lastUpdated":1791063341000}'),d={name:"quant/ap-riskadjusted-family.md"};function h(D,a,S,m,C,u){const t=s("Mermaid");return B(),p("div",null,[a[2]||(a[2]=n('<h1 id="风险调整绩效的族谱" tabindex="-1">风险调整绩效的族谱 <a class="header-anchor" href="#风险调整绩效的族谱" aria-label="Permalink to &quot;风险调整绩效的族谱&quot;">​</a></h1><div class="epigraph"><p>每一个风险调整比率都是一次压缩：分子选哪段超额，分母认哪一种离散；压缩方式不同，同一个组合的名次就不同。</p><footer>—— Sharpe, Mutual Fund Performance, Journal of Business, 1966；主动效率见 Grinold and Kahn, Active Portfolio Management</footer></div><p><a href="/quant/ap-nav-construction">上一课</a>交付了一条可复算的净值曲线。曲线只回答「赚了多少」，评估单元的缺口是「值不值这个风险」。单个比率的公式、年化与抽样误差，主干<a href="/quant/ir-sharpe">IR / Sharpe / Sortino</a>已经写透；本课写<strong>族谱</strong>：这些比率从哪两个轴上生出来、各自服务什么契约、选错了会错在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收益不可比：杠杆与运气都能把收益率抬上去，必须除以风险才能横比。但「风险」至少三种——总波动、主动波动（跟踪误差）、下行偏差；「超额」至少两种——相对现金、相对基准。分子分母的组合生出一族比率，每个成员回答不同的问题。选错成员的典型错法：给没有基准契约的绝对收益产品报 IR，分子里根本没有主动收益；给指数增强报总波动 Sharpe，把 beta 波动算成了管理人的成本；事后把 Sortino 的最低可接受收益调到让比率最大的位置——这是数据窥探，不是风险度量。</p><p><span class="marginnote">数字实例：年化收益 8%、现金利率 2%、年化波动 12% 的组合，Sharpe \\(=(8\\%-2\\%)/12\\%=0.5\\)。若换成分母为跟踪误差 3% 的 IR，而它相对基准的超额只有 0.9%，IR \\(=0.3\\)——同一份历史，两个比率讲出两档「效率」，全看分母认哪种风险。</span></p><h3 id="两个轴与三代成员" tabindex="-1">两个轴与三代成员 <a class="header-anchor" href="#两个轴与三代成员" aria-label="Permalink to &quot;两个轴与三代成员&quot;">​</a></h3><p>分子轴是<strong>超额对象</strong>：相对现金 \\(R-R_f\\)，或相对基准 \\(R_p-R_b\\)。分母轴是<strong>离散度量</strong>：全体标准差、系统性 beta、跟踪误差、下行偏差、最大回撤。族谱按此展开：Treynor（1965）取 \\(R-R_f\\) 除以 beta，只罚系统性风险；Sharpe（1966）取 \\(R-R_f\\) 除以总波动，度量总风险效率；Jensen（1968）放弃分母，把 CAPM 残差直接当 alpha；Grinold–Kahn 的 IR 换成主动收益除以跟踪误差，度量主动效率；Sortino（1991）把分母换成相对目标的下行偏差；Calmar 一族用年化收益除以最大回撤，把路径深度请回来，见<a href="/quant/drawdown-calmar">最大回撤与 Calmar</a>。三代演化的方向一致：从对称总风险，到主动风险，到非对称与路径敏感的风险。</p><p><span class="marginnote">同一份回测可以同时报出 Sharpe 1.6 与 Calmar 0.3：前者看不见 40% 的回撤，后者看不见回撤之外的全部路径。族谱成员不是竞争者，是对不同风险观的取景。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型的判据不是「哪个更科学」，而是<strong>产品契约承诺哪种效率</strong>。绝对收益产品报 Sharpe 加回撤类；指数增强与主动股票报 IR 加跟踪误差；不对称或左尾敏感的产品加 Sortino 与压力情景。报告出整套而不是挑最大的一个——只展示三家里最好的那个，与挑最好的回测是同一种选择偏差。族谱是地图，地图不替代测量精度：短样本上比率分布极宽，两位小数的排名常常超出可分辨精度。</p><p><span class="marginnote">常见误区：初学者容易把「这个比率更高」当成「这个策略更好」。比率是被分母定义的：把 Sortino 的目标收益事后调低，把 Sharpe 的无风险利率换成低利率时期，读数都能「变好」——变的不是策略，是取景框。</span></p>',12)),(B(),o(i,null,{default:e(()=>[A(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CURVE%5B%22%E5%87%80%E5%80%BC%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20EXC%5B%22%E5%88%86%E5%AD%90%3A%20%E8%B6%85%E9%A2%9D%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20CURVE%20--%3E%20RISK%5B%22%E5%88%86%E6%AF%8D%3A%20%E7%A6%BB%E6%95%A3%E5%BA%A6%E9%87%8F%22%5D%0A%20%20EXC%20--%3E%20CASH%5B%22%E7%9B%B8%E5%AF%B9%E7%8E%B0%E9%87%91%20R-R_f%22%5D%0A%20%20EXC%20--%3E%20BENCH%5B%22%E7%9B%B8%E5%AF%B9%E5%9F%BA%E5%87%86%20R_p-R_b%22%5D%0A%20%20RISK%20--%3E%20SD%5B%22%E6%80%BB%E6%B3%A2%E5%8A%A8%2Fbeta%2F%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20RISK%20--%3E%20DOWN%5B%22%E4%B8%8B%E8%A1%8C%E5%81%8F%E5%B7%AE%2F%E6%9C%80%E5%A4%A7%E5%9B%9E%E6%92%A4%22%5D%0A%20%20CASH%20--%3E%20SD%20--%3E%20SHP%5B%22Sharpe%20%2F%20Treynor%22%5D%0A%20%20CASH%20--%3E%20DOWN%20--%3E%20SRT%5B%22Sortino%20%2F%20Calmar%22%5D%0A%20%20BENCH%20--%3E%20SD%20--%3E%20IR%5B%22IR%22%5D%0A%20%20BENCH%20--%3E%20DOWN%20--%3E%20IRD%5B%22%E4%B8%BB%E5%8A%A8%20Sortino%22%5D%0A%20%20SHP%20--%3E%20SET%5B%22%E4%B8%8E%E5%A5%91%E7%BA%A6%E5%8C%B9%E9%85%8D%E7%9A%84%E6%AF%94%E7%8E%87%E5%A5%97%E8%A3%85%22%5D%0A%20%20SRT%20--%3E%20SET%0A%20%20IR%20--%3E%20SET%0A%20%20IRD%20--%3E%20SET%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[E("家族共享一个弱点：都是「一阶除二阶」的压缩，丢掉路径与极端分位。排序可翻转的机制就在分母的矩上：负偏、肥尾的策略会高估 Sharpe，因为标准差看不见偏的方向；Sortino 部分修正左尾，但仍忽略极端分位；回撤类只认最深一点，对恢复速度与回撤频率全盲。机制上不存在全功能比率，只存在「对哪类风险敏感」的取向——这就是族谱而不是排行的原因。再叠加抽样误差与被选择过的夏普（"),r("a",{href:"/quant/deflated-sharpe"},"放气夏普"),E("），任何单点评级都要先问样本长度与试验次数。")],-1)),(B(),o(i,null,{default:e(()=>[A(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E6%94%B6%E7%9B%8A%E5%8E%86%E5%8F%B2%22%5D%20--%3E%20SK%7B%22%E6%94%B6%E7%9B%8A%E5%88%86%E5%B8%83%E4%BB%80%E4%B9%88%E5%BD%A2%E7%8A%B6%3F%22%7D%0A%20%20SK%20--%3E%7C%22%E5%AF%B9%E7%A7%B0%22%7C%20OK%5B%22Sharpe%20%E8%AF%BB%E6%95%B0%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20SK%20--%3E%7C%22%E8%B4%9F%E5%81%8F%20%2F%20%E8%82%A5%E5%B0%BE%22%7C%20INFL%5B%22%E6%A0%87%E5%87%86%E5%B7%AE%E7%9C%8B%E4%B8%8D%E8%A7%81%E5%B7%A6%E5%B0%BE%2C%20Sharpe%20%E5%81%8F%E9%AB%98%22%5D%0A%20%20P%20--%3E%20DD%7B%22%E8%B7%AF%E5%BE%84%E6%9C%89%E6%B2%A1%E6%9C%89%E6%B7%B1%E5%9D%91%3F%22%7D%0A%20%20DD%20--%3E%7C%22%E6%9C%89%E6%B7%B1%E5%9B%9E%E6%92%A4%22%7C%20CAL%5B%22%E5%9B%9E%E6%92%A4%E7%B1%BB%E6%AF%94%E7%8E%87%E7%BB%99%E5%87%BA%E5%8F%A6%E4%B8%80%E5%B9%85%E9%9D%A2%E5%AD%94%22%5D%0A%20%20DD%20--%3E%7C%22%E5%B9%B3%E7%BC%93%22%7C%20OK2%5B%22%E5%9B%9E%E6%92%A4%E7%B1%BB%E5%8F%98%E5%8C%96%E4%B8%8D%E5%A4%A7%22%5D%0A%20%20INFL%20--%3E%20FLIP%5B%22%E6%8D%A2%E4%B8%80%E4%B8%AA%E5%88%86%E6%AF%8D%2C%20%E5%90%8D%E6%AC%A1%E5%B0%B1%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20CAL%20--%3E%20FLIP%0A%20%20FLIP%20--%3E%20SET%5B%22%E7%BB%93%E8%AE%BA%3A%20%E6%8A%A5%E5%A5%97%E8%A3%85%2C%20%E4%B8%8D%E6%8A%A5%E5%8D%95%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">直觉类比：比率像三位裁判给同一位体操选手打分——一位只看平均完成度（Sharpe）、一位只扣最重的一次失误（Calmar）、一位只看主动难度分（IR）。选手没有变，名次随裁判的取景翻转；所以要亮出整套打分卡，而不是只贴最高那张。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>比率不含成本与容量：毛 Sharpe 很高、净 Sharpe 近零的换手策略不少见，见<a href="/quant/net-edge">交易成本后的可交易性</a>；也不含税务与终值目标——效用、Kelly 与回撤限额都不是比率能替代的对象。基准从哪来、能不能投资、超额差分的减数怎么钉死，是下一课的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>族谱两轴：分子选超额对象（现金/基准），分母认离散（总波动/beta/跟踪误差/下行/回撤）。</li><li>三代演化：CAPM 系（Treynor、Sharpe、Jensen）到主动系（IR）到非正态路径系（Sortino、Calmar）。</li><li>选型跟着产品契约走，报套装不挑最大；事后调参数是数据窥探。</li><li>全家族都丢路径与极端分位，且带抽样误差；单点评级先问样本与试验次数。</li><li>出处：Sharpe, <em>Journal of Business</em>, 1966；Sortino and van der Meer, <em>Journal of Portfolio Management</em>, 1991；Grinold and Kahn, <em>Active Portfolio Management</em>。</li></ul>',5))])}const R=l(d,[["render",h]]);export{F as __pageData,R as default};
